Set-Location -LiteralPath $PSScriptRoot
$msg = 'diagnostics: read-only inbound SMS trace. When no Reply row exists, the three segments of the inbound leg - handset to Twilio, Twilio to our webhook, webhook to EvoSys - look identical from inside the product, and the honest answer is that we cannot tell which broke. GET /god/sms-trace/inbound/{org} reads Twilio own inbound message log for a number over a time window, and the IncomingPhoneNumber resource behind it: sms_url, sms_method, sms_fallback_url, and sms_application_sid, which when set overrides sms_url entirely so a correct looking URL can still route elsewhere. It also lists which messaging services hold the number and whether each uses use_inbound_webhook_on_number, since that decides whether the number level or service level webhook is the live one. Strictly read only - it lists and fetches, cannot send a message, and cannot modify a number, webhook, messaging service or campaign, asserted by the sweep. No Twilio configuration, A2P registration or SMS architecture changed.'
& "$PSScriptRoot\deploy.ps1" -Message $msg
Write-Output ("DEPLOY_EXIT=" + $LASTEXITCODE)
